// Typing bar removed as per user request


// Helper function for date formatting (if needed)
const formatDateSeparator = (date) => {
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  if (date.toDateString() === today.toDateString()) return 'Today';
  if (date.toDateString() === yesterday.toDateString()) return 'Yesterday';
  return date.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
};

const MessageInput = React.memo(({ onSend, replyingTo, onCancelReply, user }) => {
  const [text, setText] = useState('');
  const inputRef = useRef(null);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  useEffect(() => {
    // Focus input when starting to reply
    if (replyingTo && inputRef.current) {
      inputRef.current.focus();
    }
  }, [replyingTo]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (text.trim()) {
      onSend(text);
      setText('');
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  return (
    <Box component="form" onSubmit={handleSubmit} sx={{ p: 2, borderTop: 1, borderColor: 'divider' }}>
      {replyingTo && (
        <Box 
          sx={{ 
            mb: 1, 
            p: 1, 
            borderLeft: '4px solid #008069',
            backgroundColor: 'rgba(0, 128, 105, 0.1)',
            borderRadius: '4px',
            display: 'flex',
            alignItems: 'flex-start',
            gap: 1
          }}
        >
          <Box sx={{ flex: 1 }}>
          <Typography variant="caption" color="primary" sx={{ fontWeight: 600 }}>
              {replyingTo.senderId === user?.uid ? 'Replying to yourself' : 'Replying to message'}
          </Typography>
            <Typography 
              variant="body2" 
              sx={{ 
                color: 'text.secondary',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical'
              }}
            >
              {replyingTo.text}
            </Typography>
          </Box>
          <IconButton size="small" onClick={onCancelReply}>
            <Close fontSize="small" />
          </IconButton>
        </Box>
      )}
      <Box sx={{ display: 'flex', gap: 1 }}>
        <InputBase
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={isMobile ? "Type a message..." : "Type a message... (Press Shift+Enter for new line)"}
          fullWidth
          multiline
          rows={1}
          maxRows={3}
          sx={{
            flex: 1,
            px: 2,
            py: 1,
            backgroundColor: 'action.hover',
            borderRadius: 1,
            '& .MuiInputBase-input': {
              whiteSpace: 'normal',
              wordWrap: 'break-word',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              lineHeight: '1.5',
              display: 'block',
              width: '100%'
            }
          }}
        />
        <IconButton type="submit" disabled={!text.trim()} color="primary">
          <Send />
        </IconButton>
      </Box>
    </Box>
  );
});

const groupMessagesByDate = (messages) => {
  if (!messages.length) return [];
  const grouped = [];
  let lastDate = null;
  messages.forEach((msg) => {
    if (msg.timestamp?.toDate) {
      const msgDate = msg.timestamp.toDate();
      if (!lastDate || msgDate.toDateString() !== lastDate.toDateString()) {
        grouped.push({ type: 'date', date: msgDate, id: msgDate.getTime() });
        lastDate = msgDate;
      }
    }
    grouped.push({ type: 'message', ...msg });
  });
  return grouped;
};

