const PrivateChatRoom = React.memo(function PrivateChatRoom({ user }) {
  const { userId } = useParams();
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [processedMessages, setProcessedMessages] = useState([]);
  const [users, setUsers] = useState([]);
  const [userStatuses, setUserStatuses] = useState({});
  const [contextMenu, setContextMenu] = useState(null);
  const [otherTyping, setOtherTyping] = useState(false);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [unreadMessages, setUnreadMessages] = useState({});
  const [replyingTo, setReplyingTo] = useState(null);
  const [notification, setNotification] = useState({ open: false, message: null, sender: null });
  
  const messagesEndRef = useRef(null);
  const typingRef = useRef(null);
  const lastMessageRef = useRef(null);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md')); // Use 'md' breakpoint for consistency with App.js

  useEffect(() => {
    if (userId) {
      const userRef = doc(db, 'users', userId);
      getDoc(userRef).then((docSnap) => {
        if (docSnap.exists()) {
          setSelectedUser(docSnap.data());
        } else {
          console.log("No such document!");
          setSelectedUser(null); // Ensure selectedUser is null if not found
        }
      });
    } else {
      setSelectedUser(null); // Clear selected user if userId is not present
    }
  }, [userId]);

  useEffect(() => {
    const grouped = groupMessagesByDate(messages);
    setProcessedMessages(grouped);
  }, [messages]);

  // Removed typing-related effects

  useEffect(() => {
    if (!user) return;
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('uid', '!=', user.uid));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const userList = querySnapshot.docs.map((d) => d.data());
      setUsers(userList);
      setLoadingUsers(false);
      userList.forEach((otherUser) => {
        const statusRef = ref(rtdb, `/status/${otherUser.uid}`);
        onValue(statusRef, (snapshot) => {
          const status = snapshot.val();
          setUserStatuses((prev) => ({ ...prev, [otherUser.uid]: status }));
        });
      });
    });
    return () => unsubscribe();
  }, [user]);

  useEffect(() => {
    if (!user || !selectedUser) {
      setMessages([]);
      return;
    }
    const chatId = [user.uid, selectedUser.uid].sort().join('_');
    const messagesRef = collection(db, 'privateMessages', chatId, 'messages');
    const q = query(messagesRef, orderBy('timestamp', 'asc'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      // Get the last message from the previous state
      const lastMsg = lastMessageRef.current;
      
      // Update messages
      const msgs = querySnapshot.docs.map((d) => ({ id: d.id, ...d.data() }));
      setMessages(msgs);

      // Check for new message notification
      if (lastMsg && msgs.length > 0) {
        const newestMsg = msgs[msgs.length - 1];
        if (newestMsg.id !== lastMsg.id && newestMsg.senderId !== user.uid) {
          // Find sender info from users list
          const sender = users.find(u => u.uid === newestMsg.senderId);
          // Show notification
          setNotification({
            open: true,
            message: newestMsg.text,
            sender: sender
          });
        }
      }
      
      // Update last message reference
      lastMessageRef.current = msgs[msgs.length - 1];
      const batch = writeBatch(db);
      const unread = querySnapshot.docs.filter(
        (d) => d.data().receiverId === user.uid && !d.data().read,
      );
      if (unread.length > 0) {
        unread.forEach((d) => batch.update(d.ref, { read: true }));
        batch.commit();
      }
    });
    return () => unsubscribe();
  }, [user, selectedUser]);

  useEffect(() => {
    if (!user || users.length === 0) return;
    const unsubscribes = users.map((otherUser) => {
      const chatId = [user.uid, otherUser.uid].sort().join('_');
      const messagesRef = collection(db, 'privateMessages', chatId, 'messages');
      const q = query(messagesRef, where('receiverId', '==', user.uid), where('read', '==', false));
      return onSnapshot(q, (snapshot) => {
        setUnreadMessages((prev) => ({ ...prev, [otherUser.uid]: snapshot.size }));
      });
    });
    return () => unsubscribes.forEach((unsub) => unsub());
  }, [users, user]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [processedMessages, otherTyping]);

  // Optimized typing status handler
  const handleTypingStatus = useCallback((isTyping) => {
    if (!user || !selectedUser) return;
    const chatId = [user.uid, selectedUser.uid].sort().join('_');
    const myTypingRef = ref(rtdb, `/typing/${chatId}/${user.uid}`);
    
    // Clear previous timeout
    if (typingRef.current) {
      clearTimeout(typingRef.current);
      typingRef.current = null;
    }

    // Set typing status
    set(myTypingRef, isTyping);

    // Auto clear after 2 seconds of no updates
    if (isTyping) {
      typingRef.current = setTimeout(() => {
        set(myTypingRef, false);
      }, 2000);
    }
  }, [user, selectedUser]);

  // Watch other user's typing status
  useEffect(() => {
    if (!user || !selectedUser) return;
    const chatId = [user.uid, selectedUser.uid].sort().join('_');
    const otherTypingRef = ref(rtdb, `/typing/${chatId}/${selectedUser.uid}`);
    
    const unsubscribe = onValue(otherTypingRef, (snapshot) => {
      setOtherTyping(!!snapshot.val());
    });

    return () => {
      unsubscribe();
      // Clean up typing status when unmounting
      const myTypingRef = ref(rtdb, `/typing/${chatId}/${user.uid}`);
      set(myTypingRef, false);
    };
  }, [user, selectedUser]);

  // Message actions
  const deleteMessage = async (message) => {
    if (!selectedUser || !message || !user) return;
    const chatId = [user.uid, selectedUser.uid].sort().join('_');
    const messageRef = doc(db, 'privateMessages', chatId, 'messages', message.id);
    try {
      await deleteDoc(messageRef);
      // If this message was being replied to, cancel the reply
      if (replyingTo && replyingTo.id === message.id) {
        setReplyingTo(null);
      }
    } catch (error) {
      console.error('Error deleting message: ', error);
    }
  };

  // Function to find and highlight replied message
  const scrollToRepliedMessage = useCallback((messageId) => {
    const repliedMsg = document.getElementById(`msg-${messageId}`);
    if (repliedMsg) {
      repliedMsg.scrollIntoView({ behavior: 'smooth', block: 'center' });
      repliedMsg.classList.add('highlight');
      setTimeout(() => {
        repliedMsg.classList.remove('highlight');
      }, 2000);
    }
  }, []);

const [anchorPosition, setAnchorPosition] = useState(null);
const [selectedMessage, setSelectedMessage] = useState(null);
const [showCopied, setShowCopied] = useState(false);
const [copyAnchor, setCopyAnchor] = useState(null);

const handleContextMenu = (event, message) => {
  if (!message) return; // Don't show menu if no message is provided
  
  event.preventDefault();
  event.stopPropagation();
  
  // Prevent text selection
  if (window.getSelection) {
    window.getSelection().removeAllRanges();
  }

  setSelectedMessage(message);
  setAnchorPosition({
    left: event.clientX,
    top: event.clientY
  });
};

const handleLongPress = (event, message) => {
  if (!message) return; // Don't show menu if no message is provided
  
  event.preventDefault();
  event.stopPropagation();
  
  const rect = event.target.getBoundingClientRect();
  setSelectedMessage(message);
  setAnchorPosition({
    left: rect.left + rect.width / 2,
    top: rect.top + rect.height / 2
  });
};

const handleClose = () => {
  setAnchorPosition(null);
  setSelectedMessage(null);
};

const handleDelete = () => {
  if (selectedMessage) {
    deleteMessage(selectedMessage);
  }
  handleClose();
};

const [showComingSoon, setShowComingSoon] = useState(false);

const handleReply = () => {
  setShowComingSoon(true);
  setTimeout(() => {
    setShowComingSoon(false);
  }, 2000);
  if (selectedMessage) {
    setReplyingTo(selectedMessage);
  }
  handleClose();
};

const handleCopy = () => {
  if (selectedMessage) {
    navigator.clipboard.writeText(selectedMessage.text).then(() => {
      setCopyAnchor(anchorPosition);
      setShowCopied(true);
      setTimeout(() => {
        setShowCopied(false);
        setCopyAnchor(null);
      }, 2000);
    });
  }
  handleClose();
};  const cancelReply = () => {
    setReplyingTo(null);
  };
  
  // Optimized message sending handler
  const handleSendMessage = useCallback(async (messageText) => {
    if (!messageText.trim() || !selectedUser || !user) return;

    const chatId = [user.uid, selectedUser.uid].sort().join('_');
    const messagesRef = collection(db, 'privateMessages', chatId, 'messages');

    try {
      const messageData = {
        text: messageText,
        senderId: user.uid,
        receiverId: selectedUser.uid,
        timestamp: serverTimestamp(),
        read: false
      };

      // Add replyTo data if replying to a message
      if (replyingTo) {
        messageData.replyTo = {
          id: replyingTo.id,
          text: replyingTo.text,
          senderId: replyingTo.senderId,
          displayText: replyingTo.text.length > 50 
            ? replyingTo.text.substring(0, 50) + '...'
            : replyingTo.text
        };
        
        // Add reference to original message
        messageData.replyToId = replyingTo.id;
      }

      const docRef = await addDoc(messagesRef, messageData);
      
      // Clear reply state after sending
      if (replyingTo) {
        setReplyingTo(null);
      }
      
      // Scroll to the new message
      setTimeout(() => {
        const newMsg = document.getElementById(`msg-${docRef.id}`);
        if (newMsg) {
          newMsg.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }
      }, 100);
      
      // Scroll to bottom after sending
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } catch (error) {
      console.error('Error sending message:', error);
    }
  }, [user, selectedUser]);

  const handleLogout = () => signOut(auth);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', backgroundColor: theme.palette.background.default }}>
      <AppBar position="static" elevation={0} className="chat-room-header">
        <Toolbar sx={{ minHeight: '64px !important' }}>
          {isMobile && (
            <IconButton color="inherit" onClick={() => navigate('/')} edge="start" sx={{ mr: 1 }}>
              <ArrowBack />
            </IconButton>
          )}
          {selectedUser && (
            <StyledBadge
              status={userStatuses[selectedUser.uid]?.state || 'offline'}
              overlap="circular"
              anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
              variant="dot"
              sx={{ mr: 1 }}
            >
              <Avatar src={selectedUser.photoURL} {...stringAvatar(selectedUser.displayName)} />
            </StyledBadge>
          )}
          <Box sx={{ flexGrow: 1 }}>
            <Typography variant="h6" className="chat-room-header-name">
              {selectedUser ? selectedUser.displayName || selectedUser.email : (userId ? 'Loading...' : 'Select a user')}
            </Typography>
            {selectedUser && selectedUser.uid && (
              <Typography variant="caption" className="chat-room-header-status">
                {userStatuses[selectedUser.uid]?.state === 'online' ? 'Online' : 'Offline'}
              </Typography>
            )}
          </Box>
        </Toolbar>
      </AppBar>

      <Box className="message-list-container">
        {selectedUser ? (
          <>
            {processedMessages.map((item) => {
              if (item.type === 'date') {
                return <Box key={item.id} sx={{ display: 'flex', justifyContent: 'center', my: 2 }}><Chip label={formatDateSeparator(item.date)} sx={{ backgroundColor: '#e0e0e0', color: '#333' }} /></Box>;
              }
              const msg = item;
              return (
                <MessageItem
                  key={msg.id}
                  msg={msg}
                  user={user}
                  users={users}
                  onContextMenu={handleContextMenu}
                  onReply={handleReply}
                />
              );
            })}
          </>
        ) : (
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%' }}>
            <Typography variant="h5" color="text.secondary" sx={{ fontWeight: 400 }}>Select a user to start chatting</Typography>
          </Box>
        )}
        <div ref={messagesEndRef} />
      </Box>

      {selectedUser && (
        <Box sx={{ mt: 'auto' }}>
          <MessageInput 
            onSend={handleSendMessage}
            replyingTo={replyingTo}
            onCancelReply={cancelReply}
            user={user}
          />
        </Box>
      )}
      {/* Context Menu */}
      <Menu
        open={Boolean(anchorPosition)}
        onClose={handleClose}
        anchorReference="anchorPosition"
        anchorPosition={anchorPosition}
      >
        <MenuItem onClick={handleReply}>
          <ListItemIcon>
            <Reply fontSize="small" />
          </ListItemIcon>
          Reply
        </MenuItem>
        <MenuItem onClick={handleCopy}>
          <ListItemIcon>
            <ContentCopy fontSize="small" />
          </ListItemIcon>
          Copy
        </MenuItem>
        {selectedMessage?.senderId === user.uid && (
          <MenuItem onClick={handleDelete}>
            <ListItemIcon>
              <Delete fontSize="small" />
            </ListItemIcon>
            Delete
          </MenuItem>
        )}
      </Menu>

      {/* Copied Tooltip */}
      <Tooltip
        open={showCopied}
        onClose={() => setShowCopied(false)}
        title={
          <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
            <CheckCircle fontSize="small" color="inherit" />
            Copied!
          </div>
        }
        arrow
        placement="top"
        anchorReference="anchorPosition"
        anchorPosition={copyAnchor}
      />

      {/* Coming Soon Snackbar */}
      <Snackbar
        open={showComingSoon}
        autoHideDuration={2000}
        onClose={() => setShowComingSoon(false)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        message="Reply feature coming soon! 🚀"
        sx={{
          '& .MuiSnackbarContent-root': {
            bgcolor: '#202c33',
            color: '#e9edef',
            borderRadius: '8px',
            fontWeight: 500
          }
        }}
      />

      {/* Message Notification */}
      <MessageNotification
        open={notification.open}
        message={notification.message}
        sender={notification.sender}
        onClose={() => setNotification(prev => ({ ...prev, open: false }))}
      />
    </Box>
  );
});

export default PrivateChatRoom;
