import React, { useState } from 'react';
import { Box, Paper, Typography, useTheme, useMediaQuery } from '@mui/material';
import { useSwipeable } from 'react-swipeable';
import { useLongPress } from 'use-long-press';
import { Done, DoneAll } from '@mui/icons-material';

const MessageItem = React.memo(({ msg, user, users, onContextMenu, onReply }) => {
  const preventSelection = (e) => {
    e.preventDefault();
    if (window.getSelection) {
      window.getSelection().removeAllRanges();
    }
  };
  const [swipeAmount, setSwipeAmount] = useState(0);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handlers = useSwipeable({
    onSwiping: ({ deltaX }) => {
      // Only allow right swipe and limit to 80px
      if (deltaX > 0) {
        setSwipeAmount(Math.min(deltaX * 0.8, 80));
      }
    },
    onSwipedRight: (event) => {
      if (swipeAmount > 40) { // Trigger reply if swiped more than 40px
        onReply(msg);
        // Add haptic feedback if available
        if (window.navigator.vibrate) {
          window.navigator.vibrate(50);
        }
      }
      setSwipeAmount(0);
    },
    onSwipedLeft: () => setSwipeAmount(0),
    onTouchEndOrOnMouseUp: () => setSwipeAmount(0),
    preventDefaultTouchmoveEvent: true,
    trackMouse: false, // Touch only for better mobile experience
    delta: 5, // More sensitive swipe detection
    swipeDuration: 500, // Faster swipe detection
  });

  const longPress = useLongPress((e) => {
    e.preventDefault();
    // Prevent text selection
    if (window.getSelection) {
      window.getSelection().removeAllRanges();
    }
    onContextMenu(e, msg);
  }, {
    threshold: 500, // 500ms press required
    cancelOnMovement: true // Cancel if user moves finger
  });

  return (
    <Box
      id={`msg-${msg.id}`}
      className={`message-item ${msg.senderId === user.uid ? 'sent' : 'received'}`}
      onContextMenu={(e) => onContextMenu(e, msg)}
      onSelectStart={preventSelection}
      onMouseDown={preventSelection}
      onTouchStart={preventSelection}
      {...handlers}
      {...longPress}
      sx={{ 
        userSelect: 'none',
        WebkitUserSelect: 'none',
        MozUserSelect: 'none',
        msUserSelect: 'none',
        position: 'relative',
        transform: `translateX(${swipeAmount}px)`,
        transition: swipeAmount ? 'none' : 'all 0.2s ease-out',
  py: 1,
  px: 0,
  my: 0.5,
  maxWidth: '100%',
  width: '100%',
        borderRadius: 2,
        backgroundColor: 'transparent',
        marginLeft: msg.senderId === user.uid ? 'auto' : '8px',
        marginRight: msg.senderId === user.uid ? '8px' : 'auto',
        '&.highlight': {
          backgroundColor: 'rgba(0, 168, 132, 0.1)',
        }
      }}
    >
      <Box
        className={`message-bubble ${msg.senderId === user.uid ? 'sent' : 'received'}`}
        sx={{
          position: 'relative',
          backgroundColor: msg.senderId === user.uid ? '#dcf8c6' : '#ffffff',
          borderRadius: '8px',
          padding: '6px 56px 8px 9px',
          minWidth: '72px',
          boxShadow: '0 1px 2px rgba(0, 0, 0, 0.2)',
          display: 'block',
          maxWidth: '70%',
          verticalAlign: 'bottom'
        }}
      >
        {msg.replyTo && (
          <Box 
            sx={{ 
              mb: 1.5,
              p: 1,
              borderLeft: `4px solid ${msg.senderId === user.uid ? '#00a884' : '#53bdeb'}`,
              backgroundColor: msg.senderId === user.uid ? 'rgba(0, 168, 132, 0.08)' : 'rgba(83, 189, 235, 0.08)',
              borderRadius: '4px',
              cursor: 'pointer',
              wordBreak: 'break-word',
              '&:hover': {
                backgroundColor: msg.senderId === user.uid ? 'rgba(0, 168, 132, 0.12)' : 'rgba(83, 189, 235, 0.12)',
              }
            }}
            onClick={() => {
              // Scroll to replied message
              const repliedMsg = document.getElementById(`msg-${msg.replyTo.id}`);
              if (repliedMsg) {
                repliedMsg.scrollIntoView({ behavior: 'smooth', block: 'center' });
                repliedMsg.style.backgroundColor = 'rgba(0, 168, 132, 0.1)';
                setTimeout(() => {
                  repliedMsg.style.backgroundColor = '';
                }, 2000);
              }
            }}
          >
            <Typography variant="caption" sx={{ 
              color: msg.senderId === user.uid ? '#00a884' : '#53bdeb',
              fontWeight: 600,
              display: 'block',
              mb: 0.5
            }}>
              {msg.replyTo.senderId === user.uid ? 'You' : 'Their reply'}
            </Typography>
            <Typography 
              variant="body2" 
              sx={{ 
                color: 'text.secondary',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
              }}
            >
              {msg.replyTo.text}
            </Typography>
          </Box>
        )}
        {msg.imageUrl ? ( // If imageUrl exists, display the image
          <img
            src={msg.imageUrl}
            alt="Image"
            style={{ maxWidth: '100%', maxHeight: '200px', cursor: 'pointer' }}
            onClick={() => window.open(msg.imageUrl, '_blank')} // Open image in new tab
          />
        ) : (
          <Box> 
            <Typography 
              variant="body1" 
              sx={{ 
                overflowWrap: 'break-word',
                wordBreak: 'normal',
                color: '#000000',
                fontSize: '14.2px',
                lineHeight: '19px',
                whiteSpace: 'normal',
                fontWeight: 500,
                display: 'inline-block',
                maxWidth: '100%'
              }}
            >
              {msg.text}
            </Typography>
          </Box>
        )}
        <Box 
          className="bubble-meta"
          sx={{ 
            position: 'absolute',
            bottom: '6px',
            right: '10px',
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            minHeight: '16px',
            backgroundColor: 'inherit'
          }}
        >
          <Typography 
            variant="caption" 
            sx={{ 
              fontSize: '11px',
              color: msg.senderId === user.uid ? '#222' : '#666',
              lineHeight: 1,
              userSelect: 'none',
              fontWeight: 500
            }}
          >
            {msg.timestamp?.toDate().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </Typography>
          {msg.senderId === user.uid && (
            msg.read 
              ? <DoneAll sx={{ color: '#53bdeb', fontSize: '14px', ml: '2px' }} /> 
              : <Done sx={{ color: '#666', fontSize: '14px', ml: '2px' }} />
          )}
        </Box>
      </Box>
    </Box>
  );
});

export default MessageItem;
